64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
73	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
74	     * address shape rather than full RFC 5322 conformance.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
81	     * owner's id, customer code and registration date so the side-effect can be observed
82	     * independently of the HTTP response.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    /**
87	     * Common street-type abbreviations expanded during address normalization. Keys and values are
88	     * upper-cased so the mapping is applied after the address has been upper-cased.
89	     */
90	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
91	        "ST", "STREET",
92	        "RD", "ROAD",
93	        "AVE", "AVENUE");
94	
95	    /**
96	     * Maximum number of owners permitted in a single city. Once a city already contains this many
97	     * owners, creating another owner in that city is rejected as a conflict.
98	     */
99	    private static final int CITY_CAPACITY = 50;
100	
101	    /**
102	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
103	     * already share the current registration date, creating another owner today is rejected.
104	     */
105	    private static final int DAILY_OWNER_LIMIT = 100;
106	
107	    /**
108	     * Number of owner registrations on a single business day above which a newly created owner is
109	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
110	     * registration date, the surge is signalled in the response; the create itself still succeeds.
111	     */
112	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
113	
114	    /**
115	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
116	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
117	     * a city that is not listed has no known region and accepts any 4-digit postcode.
118	     */
119	    private static final Map<String, String> CITY_REGIONS = Map.of(
120	        "Sydney", "NSW",
121	        "Melbourne", "VIC",
122	        "Brisbane", "QLD");
123	
124	    /**
125	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
126	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
127	     */
128	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
129	        "NSW", new int[] {2000, 2099},
130	        "VIC", new int[] {3000, 3099},
131	        "QLD", new int[] {4000, 4099});
132	
133	    private final ClinicService clinicService;
134	
135	    private final OwnerMapper ownerMapper;
136	
137	    private final PetMapper petMapper;
138	
139	    private final VisitMapper visitMapper;
140	
141	    public OwnerRestControllerV1(ClinicService clinicService,
142	                                 OwnerMapper ownerMapper,
143	                                 PetMapper petMapper,
144	                                 VisitMapper visitMapper) {
145	        this.clinicService = clinicService;
146	        this.ownerMapper = ownerMapper;
147	        this.petMapper = petMapper;
148	        this.visitMapper = visitMapper;
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
154	        Collection<Owner> owners;
155	        if (lastName != null) {
156	            owners = this.clinicService.findOwnerByLastName(lastName);
157	        } else {
158	            owners = this.clinicService.findAllOwners();
159	        }
160	        if (owners.isEmpty()) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    /**
177	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
178	     * upper-cases the value, and expands common street-type abbreviations word-by-word
179	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
180	     * normalizes to the empty string. The normalized value is what the application stores, returns
181	     * and compares for household detection.
182	     *
183	     * @param address the raw address value from the request, may be {@code null}
184	     * @return the normalized address, or the empty string when none was supplied
185	     */
186	    private String normalizeAddress(String address) {
187	        if (address == null) {
188	            return "";
189	        }
190	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
191	        if (collapsed.isEmpty()) {
192	            return "";
193	        }
194	        String[] tokens = collapsed.split(" ");
195	        StringBuilder normalized = new StringBuilder();
196	        for (int i = 0; i < tokens.length; i++) {
197	            if (i > 0) {
198	                normalized.append(' ');
199	            }
200	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
201	        }
202	        return normalized.toString();
203	    }
204	
205	    /**
206	     * Rejects an owner payload that is missing or blank in any required field. The response body's
207	     * {@code errors} array lists the name of each offending field.
208	     *
209	     * @param ownerFieldsDto the owner payload to validate
210	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
211	     */
212	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
213	        List<String> missingFields = new ArrayList<>();
214	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
215	            missingFields.add("firstName");
216	        }
217	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
218	            missingFields.add("lastName");
219	        }
220	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
221	            missingFields.add("address");
222	        }
223	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
224	            missingFields.add("city");
225	        }
226	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
227	            missingFields.add("telephone");
228	        }
229	        if (!missingFields.isEmpty()) {
230	            throw new RequiredFieldsMissingException(missingFields);
231	        }
232	    }
233	
234	    /**
235	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
236	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
237	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
238	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
239	     * region accepts any 4-digit postcode.
240	     *
241	     * @param postcode the raw postcode value from the request, may be {@code null}
242	     * @param city the owner's city, used to look up the region whose range constrains the postcode
243	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
244	     */
245	    private void validatePostcode(String postcode, String city) {
246	        if (postcode == null) {
247	            return;
248	        }
249	        if (!postcode.matches("[0-9]{4}")) {
250	            throw new InvalidFieldsException(List.of("postcode"));
251	        }
252	        String region = CITY_REGIONS.get(city);
253	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
254	        if (range != null) {
255	            int value = Integer.parseInt(postcode);
256	            if (value < range[0] || value > range[1]) {
257	                throw new InvalidFieldsException(List.of("postcode"));
258	            }
259	        }
260	    }
261	
262	    /**
263	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
264	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
265	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
266	     * followed by 8 to 15 digits.
267	     *
268	     * @param telephone the raw telephone value from the request
269	     * @return the E.164 telephone (e.g. {@code +61412345678})
270	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
271	     */
272	    private String normalizeTelephone(String telephone) {
273	        if (telephone == null) {
274	            throw new InvalidFieldsException(List.of("telephone"));
275	        }
276	        String trimmed = telephone.trim();
277	        boolean international = trimmed.startsWith("+");
278	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
279	        String digits;
280	        if (international) {
281	            digits = cleaned.substring(1);
282	        } else {
283	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
284	            digits = "61" + national;
285	        }
286	        if (!digits.matches("[0-9]{8,15}")) {
287	            throw new InvalidFieldsException(List.of("telephone"));
288	        }
289	        requireValidNationalLength(digits);
290	        return "+" + digits;
291	    }
292	
293	    /**
294	     * Country codes with a fixed national-number length, checked longest-prefix first so that
295	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
296	     * digits; the North American Numbering Plan ('1') requires 10.
297	     */
298	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
299	
300	    /**
301	     * Validates that the national number (the E.164 digits after the country code) has the length
302	     * required for its country. Country codes without a known fixed length are left to the general
303	     * E.164 length check.
304	     *
305	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
306	     * @throws InvalidFieldsException if the national number is the wrong length for its country
307	     */
308	    private void requireValidNationalLength(String digits) {
309	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
310	            .filter(entry -> digits.startsWith(entry.getKey()))
311	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
312	            .ifPresent(entry -> {
313	                int nationalLength = digits.length() - entry.getKey().length();
314	                if (nationalLength != entry.getValue()) {
315	                    throw new InvalidFieldsException(List.of("telephone"));
316	                }
317	            });
318	    }
319	
320	    /**
321	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
322	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
323	     * be a syntactically valid address; the accepted value is returned lower-cased.
324	     *
325	     * @param email the raw email value from the request, may be {@code null}
326	     * @return the lower-cased email, or {@code null} when none was supplied
327	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
328	     */
329	    private String normalizeEmail(String email) {
330	        if (email == null || email.isBlank()) {
331	            return null;
332	        }
333	        String trimmed = email.trim();
334	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
335	            throw new InvalidFieldsException(List.of("email"));
336	        }
337	        return trimmed.toLowerCase(Locale.ROOT);
338	    }
339	
340	    /**
341	     * Rejects an owner that collides with an existing owner on their derived identity key. All
342	     * duplicate detection is consolidated into this single key
343	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
344	     * the former separate telephone, email and household checks.
345	     *
346	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
347	     * share the same normalized telephone. Because the telephone is the leading, always-present part
348	     * of the key, two members of the same household with <em>different</em> telephones have different
349	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
350	     * scenario in the acceptance suite exercises - is rejected.
351	     *
352	     * @param owner the owner being created, with its normalized telephone and email already applied
353	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
354	     */
355	    private void requireUniqueIdentity(Owner owner) {
356	        String telephone = owner.getTelephone();
357	        boolean taken = this.clinicService.findAllOwners().stream()
358	            .map(Owner::getTelephone)
359	            .anyMatch(existing -> existing != null && existing.equals(telephone));
360	        if (taken) {
361	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
362	        }
363	    }
364	
365	    /**
366	     * Rejects an owner that would join an existing owner's household without opting in. The household
367	     * is keyed by the owner's computed {@link OwnerMapper#householdId(Owner) household id} - the first
368	     * 12 hex characters of SHA-256 over the normalized last name and postcode - so two owners sharing
369	     * a last name and postcode belong to the same household even with different addresses or
370	     * telephones. Only owners with a postcode participate: an owner without a postcode has no
371	     * well-defined household and is never blocked here. The check is bypassed by the caller when the
372	     * request sets {@code sharesHousehold}, so a declared household member is created rather than
373	     * rejected.
374	     *
375	     * @param owner the owner being created, with its normalized fields already applied
376	     * @throws DuplicateOwnerHouseholdException if an existing owner already shares the household id
377	     */
378	    private void requireNoHouseholdDuplicate(Owner owner) {
379	        if (owner.getPostcode() == null) {
380	            return;
381	        }
382	        String householdId = ownerMapper.householdId(owner);
383	        boolean taken = this.clinicService.findAllOwners().stream()
384	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
385	        if (taken) {
386	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getPostcode());
387	        }
388	    }
389	
390	    /**
391	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
392	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
393	     * normalizes to the empty string.
394	     *
395	     * @param value the raw field value, may be {@code null}
396	     * @return the trimmed, whitespace-collapsed, lower-cased form
397	     */
398	    private String normalizeHousehold(String value) {
399	        if (value == null) {
400	            return "";
401	        }
402	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
403	    }
404	
405	    /**
406	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
407	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
408	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
409	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
410	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
411	     * returned so the result is deterministic.
412	     *
413	     * @param owner the owner being created, with its normalized telephone already applied
414	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
415	     */
416	    private Owner findPossibleDuplicate(Owner owner) {
417	        String lastName = owner.getLastName();
418	        String postcode = owner.getPostcode();
419	        if (lastName == null || postcode == null) {
420	            return null;
421	        }
422	        String telephone = owner.getTelephone();
423	        return this.clinicService.findAllOwners().stream()
424	            .filter(existing -> postcode.equals(existing.getPostcode()))
425	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
426	            .filter(existing -> existing.getTelephone() == null
427	                || !existing.getTelephone().equals(telephone))
428	            .min(Comparator.comparingInt(Owner::getId))
429	            .orElse(null);
430	    }
431	
432	    /**
433	     * Rejects an owner whose city already contains the maximum permitted number of owners
434	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
435	     * the same normalization used for the other owner household fields.
436	     *
437	     * @param city the city of the owner being created
438	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
439	     */
440	    private void requireCityHasCapacity(String city) {
441	        String normalizedCity = normalizeHousehold(city);
442	        long count = this.clinicService.findAllOwners().stream()
443	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
444	            .count();
445	        if (count >= CITY_CAPACITY) {
446	            throw new CityAtCapacityException(city);
447	        }
448	    }
449	
450	    /**
451	     * Rejects creating an owner once the given business day has already reached the maximum
452	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
453	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
454	     * registration date.
455	     *
456	     * @param registrationDate the business-day-adjusted registration date of the owner being created
457	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
458	     *     registered on that business day
459	     */
460	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
461	        long count = this.clinicService.findAllOwners().stream()
462	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
463	            .count();
464	        if (count >= DAILY_OWNER_LIMIT) {
465	            throw new DailyOwnerLimitException(registrationDate);
466	        }
467	    }
468	
469	    /**
470	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
471	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
472	     * been registered on that date. Evaluated before the new owner is persisted, so the count
473	     * reflects the owners that existed at the time of creation.
474	     *
475	     * @param registrationDate the business-day-adjusted registration date of the owner being created
476	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
477	     *     that registration date, otherwise {@code false}
478	     */
479	    private boolean isBulkSignup(LocalDate registrationDate) {
480	        long count = this.clinicService.findAllOwners().stream()
481	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
482	            .count();
483	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
484	    }
485	
486	    /**
487	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
488	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
489	     * date in the future is invalid.
490	     *
491	     * @param registrationDate the registration date supplied on the request, may be {@code null}
492	     * @throws InvalidFieldsException if the supplied date is later than today's server date
493	     */
494	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
495	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
496	            throw new InvalidFieldsException(List.of("registrationDate"));
497	        }
498	    }
499	
500	    /**
501	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
502	     * following Monday, while a weekday is returned unchanged.
503	     *
504	     * @param date the effective registration date (supplied or defaulted to the server date)
505	     * @return the same date when it is a weekday, otherwise the next Monday
506	     */
507	    private LocalDate toBusinessDay(LocalDate date) {
508	        return switch (date.getDayOfWeek()) {
509	            case SATURDAY -> date.plusDays(2);
510	            case SUNDAY -> date.plusDays(1);
511	            default -> date;
512	        };
513	    }
514	
515	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
516	    @Override
517	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
518	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
519	        validateRequiredFields(ownerFieldsDto);
520	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
521	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
522	        requireCityHasCapacity(ownerFieldsDto.getCity());
523	        String email = normalizeEmail(ownerFieldsDto.getEmail());
524	        HttpHeaders headers = new HttpHeaders();
525	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
526	        owner.setTelephone(telephone);
527	        owner.setEmail(email);
528	        requireUniqueIdentity(owner);
529	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
530	        if (!sharesHousehold) {
531	            requireNoHouseholdDuplicate(owner);
532	        }
533	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
534	        LocalDate effectiveDate = owner.getRegistrationDate() != null
535	            ? owner.getRegistrationDate() : LocalDate.now();
536	        LocalDate registrationDate = toBusinessDay(effectiveDate);
537	        owner.setRegistrationDate(registrationDate);
538	        requireDailyLimitNotReached(registrationDate);
539	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
540	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
541	        owner.setPossibleDuplicate(possibleDuplicate != null);
542	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
543	        this.clinicService.saveOwner(owner);
544	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
545	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
546	            ownerMapper.membershipLevel(owner));
547	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
548	        headers.setLocation(UriComponentsBuilder.newInstance()
549	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
550	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
551	    }
552	
553	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
554	    @Override
555	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
556	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
557	        if (currentOwner == null) {
558	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
559	        }
560	        currentOwner.setAddress(ownerFieldsDto.getAddress());
561	        currentOwner.setCity(ownerFieldsDto.getCity());
562	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
563	        currentOwner.setLastName(ownerFieldsDto.getLastName());
564	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
565	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
566	        this.clinicService.saveOwner(currentOwner);
567	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
568	    }
569	
570	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
571	    @Transactional
572	    @Override
573	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
574	        Owner owner = this.clinicService.findOwnerById(ownerId);
575	        if (owner == null) {
576	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
577	        }
578	        this.clinicService.deleteOwner(owner);
579	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
580	    }
581	
582	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
583	    @Override
584	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
585	        Owner owner = this.clinicService.findOwnerById(ownerId);
586	        if (owner == null) {
587	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
588	        }
589	        HttpHeaders headers = new HttpHeaders();
590	        Pet pet = petMapper.toPet(petFieldsDto);
591	        owner.setId(ownerId);
592	        pet.setOwner(owner);
593	        pet.getType().setName(null);
594	        this.clinicService.savePet(pet);
595	        PetDto petDto = petMapper.toPetDto(pet);
596	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
597	            .buildAndExpand(pet.getId()).toUri());
598	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
599	    }
600	
601	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
602	    @Override
603	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
604	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
605	        if (currentOwner != null) {
606	            Pet currentPet = this.clinicService.findPetById(petId);
607	            if (currentPet != null) {
608	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
609	                currentPet.setName(petFieldsDto.getName());
610	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
611	                this.clinicService.savePet(currentPet);
612	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
613	            }
614	        }
615	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
616	    }
617	
618	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
619	    @Override
620	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
621	        HttpHeaders headers = new HttpHeaders();
622	        Visit visit = visitMapper.toVisit(visitFieldsDto);
623	        Pet pet = new Pet();
624	        pet.setId(petId);
625	        visit.setPet(pet);
626	        this.clinicService.saveVisit(visit);
627	        VisitDto visitDto = visitMapper.toVisitDto(visit);
628	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
629	            .buildAndExpand(visit.getId()).toUri());
630	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
631	    }
632	
633	
634	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
635	    @Override
636	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
637	        Owner owner = this.clinicService.findOwnerById(ownerId);
638	        if (owner != null) {
639	            Pet pet = owner.getPet(petId);
640	            if (pet != null) {
641	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
642	            }
643	        }
644	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
645	    }
646	}
